import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.Bum8orMG.js";const u=JSON.parse('{"title":"UI Kit","description":"Katana UI — the planned framework-agnostic UI kit built on top of KatanaKit.","frontmatter":{"title":"UI Kit","description":"Katana UI — the planned framework-agnostic UI kit built on top of KatanaKit."},"headers":[],"relativePath":"ui-kit/index.md","filePath":"ui-kit/index.md","lastUpdated":1790432985000}'),r={name:"ui-kit/index.md"};function s(n,t,d,l,c,h){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="katana-ui" tabindex="-1">Katana UI <a class="header-anchor" href="#katana-ui" aria-label="Permalink to &quot;Katana UI&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Status</p><p><strong>Planned — design phase.</strong> This section describes an upcoming UI layer. No UI code ships in <code>katanakit-js</code> yet. The name <strong>Katana UI</strong> is provisional.</p></div><p>Katana UI is the planned UI kit for KatanaKit: design tokens, headless primitives, components, blocks, layouts and full application pages that reuse the toolkit&#39;s core services instead of rebuilding them.</p><h2 id="why-a-kit-on-top-of-the-toolkit" tabindex="-1">Why a kit on top of the toolkit <a class="header-anchor" href="#why-a-kit-on-top-of-the-toolkit" aria-label="Permalink to &quot;Why a kit on top of the toolkit&quot;">​</a></h2><p>KatanaKit already owns the invisible parts of a product — HTTP with Safe Results, storage strategies, reactive signals, theming, observers, sensors, workers and the AI assistant. Every dashboard, storefront and operational console needs exactly those capabilities on every screen. The kit exists so a team can assemble those screens from the same primitives the toolkit already guarantees.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>What it means</th></tr></thead><tbody><tr><td>Framework-agnostic core</td><td>Tokens, primitives and styles are vanilla TypeScript and CSS. Framework bindings are thin adapters.</td></tr><tr><td>Token-first styling</td><td>Components consume CSS custom properties only. Tailwind and daisyUI are optional presets, never a requirement.</td></tr><tr><td>SSR-safe</td><td>Every module guards browser-only APIs and hydrates without layout shifts.</td></tr><tr><td>Tree-shakeable</td><td>Per-component entry points and no side effects on import.</td></tr><tr><td>Accessible by default</td><td>WCAG 2.2 AA target: semantics, focus management, keyboard flows, reduced motion.</td></tr><tr><td>Safe Result aware</td><td>Data-bound components speak the same <code>{ data, error, ok }</code> contract as the HTTP client.</td></tr></tbody></table><h2 id="relationship-with-the-toolkit" tabindex="-1">Relationship with the toolkit <a class="header-anchor" href="#relationship-with-the-toolkit" aria-label="Permalink to &quot;Relationship with the toolkit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UI need</th><th>KatanaKit service</th></tr></thead><tbody><tr><td>Tables, filters, pagination</td><td><code>FetchApiManager</code>, <code>useGetApi</code></td></tr><tr><td>Theme switching and persistence</td><td><code>ThemeService</code>, <code>useInitTheme</code></td></tr><tr><td>Remembered UI state</td><td><code>StorageService</code> strategies</td></tr><tr><td>Reactive widgets and stores</td><td><code>ReactiveService</code> signals</td></tr><tr><td>Lazy blocks, infinite scroll</td><td><code>ObserverService</code>, <code>LazyLoaderService</code></td></tr><tr><td>Device capabilities</td><td><code>SensorsUtils</code>, <code>ViewportService</code></td></tr><tr><td>Chat and Gen-AI surfaces</td><td><code>AssistantService</code>, <code>adapters/assistant</code></td></tr><tr><td>Heavy computation</td><td><code>WorkerService</code></td></tr><tr><td>Formatting numbers, dates, currency</td><td><code>FormatterService</code>, <code>DatesService</code></td></tr></tbody></table><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><ul><li><strong>Application pages</strong> — eight dashboard layouts, a landing page, ten e-commerce pages, a file manager, a chat app, a four-page Gen-AI app and the Agentic Storage UI.</li><li><strong>Account flows</strong> — four auth pages, profile settings and a support/FAQ page.</li><li><strong>Building blocks</strong> — a foundation component example, 15+ ready-to-use UI blocks, 50+ common layout examples and 100+ interaction examples with plugin integrations.</li><li><strong>Theming</strong> — token-first themes with an optional Tailwind/daisyUI preset.</li><li><strong>Charts</strong> — ApexCharts behind a swappable adapter.</li><li><strong>LLM files</strong> — machine-readable artifacts so agents can consume the kit.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Backend and business logic (the kit consumes APIs, it does not own them).</li><li>Real datasets, seed content and domain-specific integrations.</li><li>Framework state managers (the reactive signals kernel covers the kit&#39;s needs).</li></ul><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a> — layers, theming, distribution and patterns.</li><li><a href="./inventory">Inventory</a> — every planned page, block, layout and interaction.</li><li><a href="./llm-files">LLM files</a> — machine-readable artifacts for AI agents.</li><li><a href="./roadmap">Roadmap</a> — delivery phases and exit criteria.</li></ul>',15)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
